def qualifying_mask(g, min_h=5, min_w=5):
 h,w=len(g),len(g[0]); mask=[[False]*w for _ in range(h)]
 rects=set()
 for top in range(h-min_h+1):
  for bot in range(top+min_h-1,h):
   # identify maximal contiguous columns whose entire band has one same value
   vals=[]
   for c in range(w):
    v=g[top][c]
    vals.append(v if all(g[r][c]==v for r in range(top,bot+1)) else None)
   c=0
   while c<w:
    if vals[c] is None: c+=1; continue
    e=c+1
    while e<w and vals[e]==vals[c]: e+=1
    if e-c>=min_w:
     rects.add((top,bot,c,e-1,vals[c]))
     for r in range(top,bot+1):
      for j in range(c,e): mask[r][j]=True
    c=e
 return mask, sorted(rects)
